34	export function NotificationProvider({ children }: { children: React.ReactNode }) {
35	  const [notifications, setNotifications] = useState<Notification[]>([]);
36	  const notificationTimeouts = useRef<Map<string, NodeJS.Timeout>>(new Map());
37	  const notificationIds = useRef<Set<string>>(new Set());
38	
39	  const addNotification = useCallback((notification: Omit<Notification, "id">) => {
40	    const dedupeKey = `${notification.type}-${notification.title}-${notification.message}`;
41	    if (notification.duration === 0 && notificationIds.current.has(dedupeKey)) return;
42	
43	    const id = Date.now().toString() + Math.random().toString(36).substr(2, 9);
44	    notificationIds.current.add(dedupeKey);
45	    setNotifications(prev => [...prev, { ...notification, id }]);
46	
47	    if (notification.duration !== 0) {
48	      const timeout = notification.duration || 5000;
49	      const timeoutId = setTimeout(() => removeNotification(id), timeout);
50	      notificationTimeouts.current.set(id, timeoutId);
51	    }
52	    return id;
53	  }, []);
54	
55	  const removeNotification = useCallback((id: string) => {
56	    setNotifications(prev => {
57	      const n = prev.find(n => n.id === id);
58	      if (n) notificationIds.current.delete(`${n.type}-${n.title}-${n.message}`);
59	      return prev.filter(n => n.id !== id);
60	    });
61	    const t = notificationTimeouts.current.get(id);
62	    if (t) { clearTimeout(t); notificationTimeouts.current.delete(id); }
63	  }, []);
64	
65	  const clearAll = useCallback(() => {
66	    notificationTimeouts.current.forEach(clearTimeout);
67	    notificationTimeouts.current.clear();
68	    notificationIds.current.clear();
69	    setNotifications([]);
70	  }, []);
71	
72	  const contextValue = useMemo(() => ({
73	    notifications, addNotification, removeNotification, clearAll,
74	  }), [notifications, addNotification, removeNotification, clearAll]);
75	
76	  return (
77	    <NotificationContext.Provider value={contextValue}>
78	      {children}
79	      <NotificationContainer />
80	    </NotificationContext.Provider>
81	  );
82	}
