293	export function useSSEConnectionMonitoring(merchantId: number) {
294	  const { addNotification, removeNotification } = useNotifications();
295	  const sseNotificationId = useRef<string | null>(null);
296	  const statusRefs = useRef({ connectionLostNotified: false, lastConnectionState: true, isInitialized: false });
297	
298	  const checkSSEConnection = useCallback(() => {
299	    const sseConnected = navigator.onLine;
300	    if (sseConnected === statusRefs.current.lastConnectionState && statusRefs.current.isInitialized) return;
301	
302	    if (!sseConnected && !statusRefs.current.connectionLostNotified) {
303	      if (sseNotificationId.current) removeNotification(sseNotificationId.current);
304	      const id = addNotification({
305	        type: "warning", title: "Real-time Updates Disconnected",
306	        message: "Payment status updates may be delayed. Reconnecting...",
307	        duration: 0,
308	        actions: [{ label: "Refresh", onClick: () => window.location.reload(), variant: "primary" }],
309	      });
310	      sseNotificationId.current = id || null;
311	      statusRefs.current.connectionLostNotified = true;
312	    } else if (sseConnected && statusRefs.current.connectionLostNotified) {
313	      if (sseNotificationId.current) { removeNotification(sseNotificationId.current); sseNotificationId.current = null; }
314	      addNotification({ type: "success", title: "Real-time Updates Restored", message: "Payment status updates are working normally.", duration: 3000 });
315	      statusRefs.current.connectionLostNotified = false;
316	    }
317	
318	    statusRefs.current.lastConnectionState = sseConnected;
319	    statusRefs.current.isInitialized = true;
320	  }, [addNotification, removeNotification]);
321	
322	  useEffect(() => {
323	    checkSSEConnection();
324	    const timer = setInterval(checkSSEConnection, 30000);
325	    return () => clearInterval(timer);
326	  }, [merchantId, checkSSEConnection]);
327	}
